query:
DELETE FROM books
WHERE id IN (
  SELECT id FROM (
    SELECT id,
           ROW_NUMBER() OVER (PARTITION BY title, authorId ORDER BY createdAt DESC) as rn
    FROM books
  ) t
  WHERE rn > 1
);

